/** 'a b c' → ['a','b','c'] (ລາຍການ emoji ແຍກດ້ວຍຍະຫວ່າງ) */
function chatEmojiList(string $s): array
{
    return array_values(array_filter(preg_split('/\s+/u', trim($s))));
}

/** ຂໍ້ຄວາມທັງໝົດເປັນສະຕິກເກີ 1 ອັນ ຈາກລາຍການ (ບັອດບໍ່ຕອບ, ໜ້າແຊັດສະແດງໃຫຍ່) */
function chatIsSticker(string $text): bool
{
    foreach (chatStickers() as $g) {
        if (in_array($text, $g['items'], true)) {
            return true;
        }
    }
    return false;
}
